INSERT INTO access_control_role_permissions (role_id, permission_id)
SELECT r.id, p.id
FROM access_control_roles r
JOIN access_control_permissions p ON p.permission_key IN (
  'platform.tenants.manage',
  'platform.tenants.read',
  'platform.breakglass',
  'platform.roles.define',
  'platform.roles.assign',
  'platform.scope.vet',
  'platform.clone.review',
  'platform.skills.mint',
  'platform.skills.release',
  'platform.arena.run',
  'clone.read',
  'clone.configure',
  'clone.publish.staging',
  'clone.publish.live.request',
  'knowledge.manage',
  'scope.request',
  'transcripts.read',
  'conversation.takeover',
  'keys.manage',
  'webhooks.manage',
  'templates.manage',
  'usage.read',
  'users.manage',
  'roles.assign')
WHERE r.role_key = 'platform-super-admin';

